function validate([reward1, reward2, k]) {
  if (!Array.isArray(reward1) || reward1.length < 1 || reward1.length > 100000) return 'reward1 needs 1 to 10^5 values.';
  if (!Array.isArray(reward2) || reward2.length !== reward1.length) return 'reward1 and reward2 must have the same length.';
  if (reward1.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each reward1 value is between 1 and 1000.';
  if (reward2.some(v => !Number.isInteger(v) || v < 1 || v > 1000)) return 'Each reward2 value is between 1 and 1000.';
  if (!Number.isInteger(k) || k < 0 || k > reward1.length) return 'k is between 0 and the number of cheeses.';
  return null;
}

