function miceAndCheese(reward1, reward2, k) {
  const n = reward1.length;
  let total = 0;
  const gains = [];
  for (let i = 0; i < n; i++) {
    total += reward2[i];
    gains.push(reward1[i] - reward2[i]);
  }
  gains.sort((a, b) => b - a);
  for (let i = 0; i < k; i++) {
    total += gains[i];
  }
  return total;
}

