function miceAndCheese(reward1, reward2, k) {
  // Try every set of cheeses for the first mouse and keep the sets of size exactly k.
  const n = reward1.length;
  let best = -Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    let count = 0;
    let points = 0;
    for (let i = 0; i < n; i++) {
      if (mask & (1 << i)) {
        count++;
        points += reward1[i];
      } else {
        points += reward2[i];
      }
    }
    if (count === k && points > best) best = points;
  }
  return best;
}

