function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 8);
    // A narrow range makes ties between differences common; a wide one tests large values.
    const top = rand() < 0.5 ? 4 : 1000;
    const reward1 = Array.from({ length: n }, () => int(1, top));
    const reward2 = Array.from({ length: n }, () => int(1, top));
    const roll = rand();
    const k = roll < 0.15 ? 0 : roll < 0.3 ? n : int(0, n);
    return [reward1, reward2, k];
  }
  const n = 2000;
  const reward1 = Array.from({ length: n }, () => int(1, 1000));
  const reward2 = Array.from({ length: n }, () => int(1, 1000));
  return [reward1, reward2, int(0, n)];
}
